function camelToSnake(str) {
  if (typeof str !== 'string') {
    throw new TypeError('Argument must be a string');
  }

  if (!/[A-Z]/.test(str)) {
    return str;
  }

  // Step 1: Insert underscore between lower-case/digit and upper-case
  str = str.replace(/([a-z0-9])([A-Z])/g, '$1_$2');

  // Step 2: Insert underscore between upper-case and upper-case followed by lower-case
  // This handles acronyms like 'HTTP' in 'HTTPServer' -> 'HTTP_Server'
  str = str.replace(/([A-Z]+)([A-Z][a-z])/g, '$1_$2');

  return str.toLowerCase();
}

module.exports = { camelToSnake };
