function parseQuery(qs) {
  if (typeof qs !== 'string') {
    throw new TypeError('Query string must be a string');
  }

  if (!qs || qs.length === 0 || qs === '?') {
    return {};
  }

  let input = qs;
  if (input.startsWith('?')) {
    input = input.slice(1);
  }

  if (input.length === 0) {
    return {};
  }

  const result = {};
  const pairs = input.split('&');

  for (const pair of pairs) {
    if (pair.length === 0) {
      continue;
    }

    const eqIndex = pair.indexOf('=');
    let keyStr, valueStr;

    if (eqIndex === -1) {
      keyStr = pair;
      valueStr = '';
    } else {
      keyStr = pair.slice(0, eqIndex);
      valueStr = pair.slice(eqIndex + 1);
    }

    // Decode key: replace + with space, then decodeURIComponent
    let decodedKey;
    try {
      const encodedKey = keyStr.replace(/\+/g, ' ');
      decodedKey = decodeURIComponent(encodedKey);
    } catch (e) {
      if (e instanceof URIError) {
        throw e;
      }
      throw new URIError('Invalid percent-encoding in key');
    }

    if (decodedKey.length === 0) {
      continue;
    }

    // Decode value
    let decodedValue;
    try {
      const encodedValue = valueStr.replace(/\+/g, ' ');
      decodedValue = decodeURIComponent(encodedValue);
    } catch (e) {
      if (e instanceof URIError) {
        throw e;
      }
      throw new URIError('Invalid percent-encoding in value');
    }

    if (Object.prototype.hasOwnProperty.call(result, decodedKey)) {
      const existing = result[decodedKey];
      if (Array.isArray(existing)) {
        existing.push(decodedValue);
      } else {
        result[decodedKey] = [existing, decodedValue];
      }
    } else {
      result[decodedKey] = decodedValue;
    }
  }

  return result;
}

