function topoSort(graph) {
  const allTasks = new Set();
  const inDegree = new Map();
  const adjList = new Map();

  // Initialize: collect all task names (keys and values in dependency lists)
  for (const task in graph) {
    allTasks.add(task);
    if (!inDegree.has(task)) {
      inDegree.set(task, 0);
    }
    if (!adjList.has(task)) {
      adjList.set(task, []);
    }
  }

  // Process dependencies: for each task, its dependencies must come before it.
  // We'll build a directed graph where edge A -> B means A must come before B.
  // So if graph[B] contains A, then A -> B.
  for (const task of allTasks) {
    const deps = graph[task] || [];
    const uniqueDeps = [...new Set(deps)];
    for (const dep of uniqueDeps) {
      allTasks.add(dep);
      if (!inDegree.has(dep)) {
        inDegree.set(dep, 0);
      }
      if (!adjList.has(dep)) {
        adjList.set(dep, []);
      }
      if (!adjList.has(task)) {
        adjList.set(task, []);
      }
      // dep -> task (dep must come before task)
      adjList.get(dep).push(task);
      inDegree.set(task, inDegree.get(task) + 1);
    }
  }

  // Initialize queue with nodes having in-degree 0
  const queue = [];
  for (const task of allTasks) {
    if (inDegree.get(task) === 0) {
      queue.push(task);
    }
  }

  // Sort initial queue to pick lexicographically smallest first
  queue.sort();

  const result = [];

  while (queue.length > 0) {
    // Pick the smallest name
    queue.sort();
    const current = queue.shift();
    result.push(current);

    const neighbors = adjList.get(current) || [];
    for (const neighbor of neighbors) {
      inDegree.set(neighbor, inDegree.get(neighbor) - 1);
      if (inDegree.get(neighbor) === 0) {
        queue.push(neighbor);
      }
    }
  }

  // If result doesn't include all tasks, there's a cycle
  if (result.length !== allTasks.size) {
    throw new Error('Cycle detected');
  }

  return result;
}

module.exports = { topoSort };
