from datetime import date, datetime
from typing import Iterable

def business_days(start: str, end: str, holidays: Iterable[str] = ()) -> int:
    """Count business days in the half-open range [start, end)."""
    try:
        start_dt = datetime.fromisoformat(start).date()
    except (TypeError, ValueError) as e:
        raise ValueError(f"Invalid start date: {start}") from e

    try:
        end_dt = datetime.fromisoformat(end).date()
    except (TypeError, ValueError) as e:
        raise ValueError(f"Invalid end date: {end}") from e

    if end_dt < start_dt:
        raise ValueError("end must not be earlier than start")

    if start_dt == end_dt:
        return 0

    holiday_set = set()
    for h in holidays:
        try:
            holiday_dt = datetime.fromisoformat(h).date()
        except (TypeError, ValueError) as e:
            raise ValueError(f"Invalid holiday date: {h}") from e
        holiday_set.add(holiday_dt)

    count = 0
    current = start_dt

    while current < end_dt:
        if current.weekday() < 5 and current not in holiday_set:
            count += 1
        current = current.replace(day=current.day + 1)  # type: ignore
        # Handle day overflow by adding 1 day properly
        from datetime import timedelta
        current = current.replace(day=current.day) + timedelta(days=1)

    return count
