function camelToSnake(str) {
  if (typeof str !== 'string') {
    throw new TypeError('Argument must be a string');
  }

  if (!/[A-Z]/.test(str)) {
    return str;
  }

  let result = '';
  for (let i = 0; i < str.length; i++) {
    const char = str[i];
    const nextChar = str[i + 1];
    const prevChar = str[i - 1];

    const isUpper = /[A-Z]/.test(char);
    const isLower = /[a-z]/.test(char);
    const isDigit = /\d/.test(char);

    // Case 1: Insert underscore between lower-case/digit and following upper-case
    if ((isLower || isDigit) && isUpper) {
      result += '_' + char;
      continue;
    }

    // Case 2: Insert underscore between upper-case and following upper-case
    // that is followed by a lower-case letter (end of an acronym)
    if (isUpper && nextChar && /[A-Z]/.test(nextChar) && /[a-z]/.test(nextChar)) {
      result += '_' + char;
      continue;
    }

    result += char;
  }

  return result.toLowerCase();
}

