function topoSort(graph) {
  const inDegree = new Map();
  const adj = new Map();
  const allTasks = new Set();

  // Initialize in-degree and adjacency list
  for (const task in graph) {
    allTasks.add(task);
    if (!inDegree.has(task)) {
      inDegree.set(task, 0);
    }
    if (!adj.has(task)) {
      adj.set(task, []);
    }
    // Dependencies must come before this task.
    // So for each dep d, we have an edge d -> task.
    const deps = graph[task];
    for (const dep of deps) {
      allTasks.add(dep);
      if (!inDegree.has(dep)) {
        inDegree.set(dep, 0);
      }
      if (!adj.has(dep)) {
        adj.set(dep, []);
      }
      adj.get(dep).push(task);
    }
  }

  // Compute in-degrees based on edges d -> task
  // inDegree[task] = number of dependencies that must come before it
  // But we already built edges from dep -> task, so inDegree[task] is the count of incoming edges.
  // We need to recompute inDegree properly:
  // Actually, the above logic sets edges from dep -> task, so inDegree[task] should be the number of such edges.
  // Let's recompute inDegree by counting incoming edges.
  const newInDegree = new Map();
  for (const task of allTasks) {
    newInDegree.set(task, 0);
  }
  for (const [from, toList] of adj.entries()) {
    for (const to of toList) {
      newInDegree.set(to, (newInDegree.get(to) || 0) + 1);
    }
  }

  // Use a min-heap (sorted array) to pick smallest task by name
  const queue = [];
  for (const task of allTasks) {
    if (newInDegree.get(task) === 0) {
      queue.push(task);
    }
  }
  queue.sort();

  const result = [];
  while (queue.length > 0) {
    // Pick smallest
    queue.sort();
    const task = queue.shift();
    result.push(task);

    const neighbors = adj.get(task) || [];
    for (const neighbor of neighbors) {
      const newDeg = newInDegree.get(neighbor) - 1;
      newInDegree.set(neighbor, newDeg);
      if (newDeg === 0) {
        queue.push(neighbor);
      }
    }
  }

  if (result.length !== allTasks.size) {
    throw new Error('Cycle detected in dependencies');
  }

  return result;
}

