    const prevChar = i > 0 ? str[i - 1] : '';
    const currChar = str[i];
    const nextChar = i < str.length - 1 ? str[i + 1] : '';

    let insertUnderscore = false;

    // Rule 1: Between lower-case/digit and following upper-case letter
    const isPrevLowerOrDigit = /[a-z0-9]/.test(prevChar);
    const isCurrUpper = /[A-Z]/.test(currChar);

    if (isPrevLowerOrDigit && isCurrUpper) {
      insertUnderscore = true;
    }

    // Rule 2: Between upper-case and following upper-case that is followed by lower-case
    // This handles the end of an acronym: e.g., "HTTP" in "HTTPServer" -> "HTTP_Server"
    // Specifically: Upper followed by Upper followed by Lower
    const isPrevUpper = /[A-Z]/.test(prevChar);
    const isNextLower = /[a-z]/.test(nextChar);

    if (isPrevUpper && isCurrUpper && isNextLower) {
      insertUnderscore = true;
    }

    if (insertUnderscore) {
      result += '_';
    }

    result += currChar.toLowerCase();
  }

  return result;
}

