function topoSort(graph) {
  const nodes = new Set();
  const inDegree = new Map();
  const adj = new Map();

  // Initialize all nodes
  for (const task of Object.keys(graph)) {
    nodes.add(task);
  }
  // Add dependency-only tasks
  for (const deps of Object.values(graph)) {
    for (const dep of deps) {
      nodes.add(dep);
    }
  }

  // Initialize maps
  for (const node of nodes) {
    inDegree.set(node, 0);
    adj.set(node, new Set());
  }

  // Build graph and count in-degrees
  const seen = new Set();
  for (const task of Object.keys(graph)) {
    const deps = graph[task];
    for (const dep of deps) {
      if (seen.has(`${dep}-${task}`)) continue;
      seen.add(`${dep}-${task}`);
      adj.get(dep).add(task);
      inDegree.set(task, inDegree.get(task) + 1);
    }
  }

  // Get all nodes with in-degree 0
  const available = [];
  for (const node of nodes) {
    if (inDegree.get(node) === 0) {
      available.push(node);
    }
  }
  available.sort();

  const result = [];
  while (available.length > 0) {
    // Pick smallest
    const node = available.shift();
    result.push(node);

    for (const neighbor of adj.get(node)) {
      const newDegree = inDegree.get(neighbor) - 1;
      inDegree.set(neighbor, newDegree);
      if (newDegree === 0) {
        available.push(neighbor);
        available.sort();
      }
    }
  }

  if (result.length !== nodes.size) {
    throw new Error("Cycle detected in dependencies");
  }

  return result;
}

module.exports = { topoSort };
