    if not isinstance(text, str):
        raise TypeError("text must be a string")

    if not text:
        raise ValueError("empty string")

    units_order = ['d', 'h', 'm', 's']
    unit_seconds = {'d': 86400, 'h': 3600, 'm': 60, 's': 1}

    total_seconds = 0
    seen_units = []

    i = 0
    n = len(text)

    while i < n:
        if not text[i].isdigit() and not (text[i] == '-' and i < n - 1 and text[i+1].isdigit()):
            raise ValueError("unexpected character")

        if text[i] == '-':
            raise ValueError("signs not allowed")

        num_str = []
        while i < n and text[i].isdigit():
            num_str.append(text[i])
            i += 1

        if not num_str:
            raise ValueError("number without a unit")

        number = int(''.join(num_str))

        if i >= n:
            raise ValueError("unit missing")

        unit = text[i]
        i += 1

        if unit not in unit_seconds:
            raise ValueError("unknown unit")

        if unit in seen_units:
            raise ValueError("repeated unit")

        seen_units.append(unit)

        if len(seen_units) > 1:
            last_unit = seen_units[-2]
            if units_order.index(unit) >= units_order.index(last_unit):
                raise ValueError("out of order units")

        total_seconds += number * unit_seconds[unit]

    if not seen_units:
        raise ValueError("no valid duration parts found")

    return total_seconds
