from datetime import date, timedelta

def business_days(start: str, end: str, holidays=()) -> int:
    """Count working days in the half-open range [start, end)."""
    def parse_date(s: str) -> date:
        try:
            year = int(s[0:4])
            month = int(s[5:7])
            day = int(s[8:10])
            if s != f"{year:04d}-{month:02d}-{day:02d}":
                raise ValueError("Invalid date format")
            return date(year, month, day)
        except Exception:
            raise ValueError(f"Invalid date string: {s}")

    start_date = parse_date(start)
    end_date = parse_date(end)

    if end_date < start_date:
        raise ValueError("end must not be earlier than start")

    if start_date == end_date:
        return 0

    holiday_set = set()
    for h in holidays:
        try:
            year = int(h[0:4])
            month = int(h[5:7])
            day = int(h[8:10])
            if h != f"{year:04d}-{month:02d}-{day:02d}":
                raise ValueError("Invalid holiday format")
            holiday_set.add(date(year, month, day))
        except Exception:
            raise ValueError(f"Invalid holiday string: {h}")

    count = 0
    current = start_date
    while current < end_date:
        if current.weekday() < 5 and current not in holiday_set:
            count += 1
        current += timedelta(days=1)

    return count
