function topoSort(graph) {
  const inDegree = {};
  const adj = {};
  const allTasks = new Set();

  // Initialize all tasks (keys and dependency targets)
  for (const [task, deps] of Object.entries(graph)) {
    allTasks.add(task);
    for (const dep of deps) {
      allTasks.add(dep);
    }
  }

  // Initialize inDegree and adj for all tasks
  for (const task of allTasks) {
    inDegree[task] = 0;
    adj[task] = [];
  }

  // Build graph: for each task, edges go from dependencies to the task
  // (i.e., dep -> task means task depends on dep)
  for (const [task, deps] of Object.entries(graph)) {
    // Deduplicate dependencies
    const uniqueDeps = new Set(deps);
    for (const dep of uniqueDeps) {
      if (!adj[dep]) {
        // This should not happen since we added all tasks above, but safety:
        continue;
      }
      adj[dep].push(task);
      inDegree[task] = (inDegree[task] || 0) + 1;
    }
  }

  // Min-heap simulation using a sorted array (since we need smallest string)
  const ready = [];
  for (const task of allTasks) {
    if (inDegree[task] === 0) {
      ready.push(task);
    }
  }
  ready.sort();

  const result = [];
  const processed = new Set();

  while (ready.length > 0) {
    // Pick smallest
    ready.sort();
    const task = ready.shift();
    result.push(task);
    processed.add(task);

    // Process neighbors
    for (const neighbor of adj[task]) {
      inDegree[neighbor]--;
      if (inDegree[neighbor] === 0) {
        ready.push(neighbor);
      }
    }
  }

  if (result.length !== allTasks.size) {
    throw new Error('Cycle detected in dependencies');
  }

  return result;
}

