  for (const node in graph) {
    if (!Object.prototype.hasOwnProperty.call(graph, node)) continue;
    allNodes.add(node);
    inDegree[node] = inDegree[node] || 0;
    adjacency[node] = adjacency[node] || [];
  }

  // Process dependencies: for each node, its dependencies are prerequisites
  // So if node 'a' has dependency 'b', then 'b' -> 'a'
  for (const node in graph) {
    if (!Object.prototype.hasOwnProperty.call(graph, node)) continue;
    const deps = graph[node];
    // Deduplicate dependencies
    const uniqueDeps = [...new Set(deps)];
    for (const dep of uniqueDeps) {
      allNodes.add(dep);
