      if (!adjacency.hasOwnProperty(node)) {
        adjacency[node] = [];
      }
      // Edge from dep to node
      adjacency[dep].push(node);
      inDegree[node]++;
    }
  }

  // Initialize queue with nodes having in-degree 0, sorted by name
  const ready = [];
  for (const node of allNodes) {
    if (inDegree[node] === 0) {
      ready.push(node);
    }
  }
  ready.sort();

  const result = [];
  const visited = new Set();

