from typing import Iterable

def _parse_date(s: str) -> date:
    try:
        parts = s.split('-')
        if len(parts) != 3:
            raise ValueError("Invalid date format")
        year, month, day = int(parts[0]), int(parts[1]), int(parts[2])
        return date(year, month, day)
