function camelToSnake(str) {
  if (typeof str !== 'string') {
    throw new TypeError('Argument must be a string');
  }

  if (!/[A-Z]/.test(str)) {
    return str;
  }

  // Insert underscores:
  // 1. Between lower-case or digit and following upper-case letter
  // 2. Between upper-case letter and following upper-case letter that is followed by a lower-case letter
  // We use a regex with a replacement function to handle the logic carefully.
  // Pattern explanation:
  // - ([a-z0-9])([A-Z])       : group1 is lower/digit, group2 is upper -> insert underscore
  // - ([A-Z]+)([A-Z][a-z])    : group1 is a sequence of upper (acronym), group2 is the first upper of the next word (which has a lower following)
  //   We need to split the sequence before the last upper of the acronym.
  //   So we look for: one or more upper, then an upper that is followed by a lower.
  //   We want to insert underscore between the last upper of the acronym and the next upper.
  //   Regex: ([A-Z])([A-Z][a-z]) matches an upper followed by an upper+lower.
  //   We insert underscore between them.

  let result = str
    // First pass: handle lower/digit followed by upper
    .replace(/([a-z0-9])([A-Z])/g, '$1_$2')
    // Second pass: handle acronym end (upper followed by upper+lower)
    .replace(/([A-Z])([A-Z][a-z])/g, '$1_$2');

  return result.toLowerCase();
}

