  const inDegree = new Map();
  const adj = new Map();

  // Initialize nodes and adjacency list
  for (const [node, deps] of Object.entries(graph)) {
    if (!inDegree.has(node)) {
      inDegree.set(node, 0);
      adj.set(node, []);
    }
    allNodes.add(node);
    for (const dep of deps) {
      if (!inDegree.has(dep)) {
        inDegree.set(dep, 0);
        adj.set(dep, []);
      }
      allNodes.add(dep);
    }
  }

