  // Also calculate in-degrees based on the input graph structure
  // Input: node -> [deps] means node depends on deps.
  // So we have edges: dep -> node
  for (const [node, deps] of Object.entries(graph)) {
    const uniqueDeps = [...new Set(deps)];
    for (const dep of uniqueDeps) {
      adj.get(dep).push(node);
      inDegree.set(node, (inDegree.get(node) || 0) + 1);
    }
  }

