        throw new TypeError('n must be an integer');
      }
      if (!Number.isFinite(n)) {
        throw new TypeError('n must be a finite number (NaN or Infinity are not allowed)');
      }
    }
    if (n < 0) {
      throw new RangeError('n must not be negative');
    }
  }

  const units = ['B', 'KB', 'MB', 'GB', 'TB'];
  let value = n;
  let unitIndex = 0;

  while (unitIndex < units.length - 1 && value >= 1024) {
    value /= 1024;
    unitIndex++;
  }

  if (value >= 1024 && unitIndex === units.length - 1) {
    // Cap at TB, but if it's exactly 1024 TB, we still show it as TB
    // No further unit to move to, so we keep it as is
  }

  const rounded = Math.round(value * 10) / 10;

  if (rounded >= 1024 && unitIndex < units.length - 1) {
    // Rounding pushed us to 1024 in current unit; move up
    value = rounded / 1024;
    unitIndex++;
    // Handle edge case where after moving up, we might hit 1024 TB again (only possible if input was huge)
    if (unitIndex === units.length - 1 && value >= 1024) {
      // Stay at TB, no further units
    }
  }

  let result;
  if (Number.isInteger(rounded) || rounded % 1 !== 0) {
    // If it's an integer or not ending in .0
    const isInteger = Number.isInteger(rounded) || Math.abs(rounded - Math.round(rounded)) < 1e-9;
    if (isInteger) {
      result = `${Math.round(rounded)} ${units[unitIndex]}`;
    } else {
      result = `${rounded} ${units[unitIndex]}`;
    }
  } else {
    result = `${Math.round(rounded)} ${units[unitIndex]}`;
  }

  // Normalize to remove .0 if present
  if (result.includes('.0')) {
    result = result.replace('.0', '');
  }

  return result;
