class Emitter {
  constructor() {
    this._listeners = new Map();
    this._onceListeners = new Map();
  }

  _addListener(event, fn, once = false) {
    if (typeof fn !== 'function') {
      throw new TypeError('Listener must be a function');
    }

    if (this._listeners.has(event)) {
      this._listeners.get(event).push(fn);
    } else {
      this._listeners.set(event, [fn]);
    }

    if (once) {
      if (!this._onceListeners.has(event)) {
        this._onceListeners.set(event, []);
      }
      this._onceListeners.get(event).push(fn);
    }

    return this;
  }

  on(event, fn) {
    return this._addListener(event, fn, false);
  }

  once(event, fn) {
    return this._addListener(event, fn, true);
  }

  off(event, fn) {
    if (event === undefined) {
      this._listeners.clear();
      this._onceListeners.clear();
      return this;
    }

    if (fn === undefined) {
      this._listeners.delete(event);
      this._onceListeners.delete(event);
      return this;
    }

    const listeners = this._listeners.get(event);
    if (listeners) {
      const idx = listeners.indexOf(fn);
      while (idx !== -1) {
        listeners.splice(idx, 1);
        const nextIdx = listeners.indexOf(fn, idx);
        idx = nextIdx === -1 ? -1 : nextIdx;
      }
      if (listeners.length === 0) {
        this._listeners.delete(event);
      }
    }

    const onceListeners = this._onceListeners.get(event);
    if (onceListeners) {
      const idx = onceListeners.indexOf(fn);
      while (idx !== -1) {
        onceListeners.splice(idx, 1);
        const nextIdx = onceListeners.indexOf(fn, idx);
        idx = nextIdx === -1 ? -1 : nextIdx;
      }
      if (onceListeners.length === 0) {
        this._onceListeners.delete(event);
      }
    }

    return this;
  }

  emit(event, ...args) {
    const listeners = this._listeners.get(event);
    if (!listeners || listeners.length === 0) {
      return false;
    }

    const toRemove = [];
    const listenersCopy = listeners.slice();

    for (let i = 0; i < listenersCopy.length; i++) {
      const fn = listenersCopy[i];
      const isOnce = this._onceListeners.has(event) && 
                     this._onceListeners.get(event).indexOf(fn) !== -1;

      if (isOnce) {
        toRemove.push(fn);
      }

      fn.apply(this, args);
    }

    if (toRemove.length > 0) {
      this.off(event, undefined); // Clear all once listeners for this event
      const listenersSet = this._listeners.get(event);
      if (listenersSet) {
        toRemove.forEach(fn => {
          const idx = listenersSet.indexOf(fn);
          if (idx !== -1) {
