          }
        });
        if (listenersSet.length === 0) {
          this._listeners.delete(event);
        }
      }
    }

    return true;
  }

  listenerCount(event) {
    const listeners = this._listeners.get(event);
    return listeners ? listeners.length : 0;
  }
}

