function expandRanges(spec) {
  if (typeof spec !== 'string') {
    throw new TypeError('spec must be a string');
  }

  const parts = spec.split(',');
  const result = new Set();

  for (const part of parts) {
    const trimmed = part.trim();
    if (trimmed === '') {
      continue;
    }

    if (!trimmed.includes('-')) {
      // Single number
      const num = parseInt(trimmed, 10);
      if (isNaN(num) || !/^\d+$/.test(trimmed)) {
        throw new SyntaxError(`Invalid part: ${part}`);
      }
      result.add(num);
      continue;
    }

    const dashIndex = trimmed.indexOf('-');
    if (trimmed.indexOf('-', dashIndex + 1) !== -1) {
      throw new SyntaxError(`Invalid part: ${part} (more than one dash)`);
    }

    const loStr = trimmed.substring(0, dashIndex);
    const hiStr = trimmed.substring(dashIndex + 1);

    if (loStr === '' || hiStr === '') {
      throw new SyntaxError(`Invalid part: ${part} (missing start or end)`);
    }

    if (!/^\d+$/.test(loStr) || !/^\d+$/.test(hiStr)) {
      throw new SyntaxError(`Invalid part: ${part}`);
    }

    const lo = parseInt(loStr, 10);
    const hi = parseInt(hiStr, 10);

    if (lo > hi) {
      throw new RangeError(`Invalid range: ${part} (start greater than end)`);
    }

    for (let n = lo; n <= hi; n++) {
      result.add(n);
    }
  }

  return Array.from(result).sort((a, b) => a - b);
}

module.exports = { expandRanges };
