def parse_csv_line(line):
    if not isinstance(line, str):
        raise TypeError("line must be a string")

    result = []
    i = 0
    n = len(line)

    while True:
        if i >= n:
            # End of line reached
            if result == []:
                # Empty input or just finished processing; ensure we return [""] for empty string
                result.append("")
            break

        # Determine if current field is quoted
        if line[i] == '"':
            # Start of a quoted field
            i += 1  # skip opening quote
            field_chars = []

            while i < n:
                if line[i] == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        # Escaped quote
                        field_chars.append('"')
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        break
                else:
                    field_chars.append(line[i])
                    i += 1
            else:
                # Reached end of line without closing quote
                raise ValueError("Unclosed quoted field")

            result.append("".join(field_chars))

            # After closing quote, must be comma or end of line
            if i < n:
                if line[i] == ',':
                    i += 1
                else:
                    raise ValueError("Invalid character after quoted field")
        else:
            # Unquoted field: read until comma or end of line
            start = i
            while i < n and line[i] != ',':
                i += 1
            field = line[start:i]
            result.append(field)

            if i < n and line[i] == ',':
                i += 1

    return result
