def rle_encode(s):
    if not isinstance(s, str):
        raise TypeError("Input must be a string")
    if any(c.isdigit() for c in s):
        raise ValueError("Input must not contain any digit character")

    if not s:
        return ""

    result = []
    count = 1
    prev = s[0]

    for i in range(1, len(s)):
        c = s[i]
        if c == prev:
            count += 1
        else:
            result.append(f"{count}{prev}")
            count = 1
            prev = c

    result.append(f"{count}{prev}")
    return "".join(result)


def rle_decode(s):
    if not isinstance(s, str):
        raise TypeError("Input must be a string")

    if not s:
        return ""

    result = []
    i = 0
    n = len(s)

    while i < n:
        # Extract count (digits)
        start = i
        while i < n and s[i].isdigit():
            i += 1

        if start == i:
            raise ValueError("Missing count")

        count_str = s[start:i]
        count = int(count_str)

        if count == 0:
            raise ValueError("Count of zero is not allowed")

        # Extract character (must be non-digit)
        if i >= n:
            raise ValueError("Trailing digits with no character")

        if s[i].isdigit():
            raise ValueError("Character must be a non-digit")

        char = s[i]
        i += 1

        result.append(char * count)

    return "".join(result)
