function expandRanges(spec) {
  if (typeof spec !== 'string') {
    throw new TypeError('spec must be a string');
  }

  const parts = spec.split(',');
  const result = new Set();

  for (const part of parts) {
    const trimmed = part.trim();
    if (trimmed === '') {
      throw new SyntaxError('Empty part detected');
    }

    const dashIndex = trimmed.indexOf('-');

    if (dashIndex === -1) {
      // Single number
      const num = Number(trimmed);
      if (!Number.isFinite(num) || trimmed !== String(num)) {
        throw new SyntaxError('Invalid number format');
      }
      if (num < 0 || !Number.isInteger(num)) {
        throw new SyntaxError('Number must be a non-negative integer');
      }
      result.add(num);
    } else if (dashIndex === 0 || dashIndex === trimmed.length - 1) {
      // Leading or trailing dash, or double dash
      throw new SyntaxError('Invalid range format');
    } else {
      // Range with exactly one dash
      const left = trimmed.substring(0, dashIndex);
      const right = trimmed.substring(dashIndex + 1);

      const lo = Number(left);
      const hi = Number(right);

      if (!Number.isFinite(lo) || !Number.isFinite(hi)) {
        throw new SyntaxError('Invalid number format in range');
      }
      if (lo < 0 || hi < 0 || !Number.isInteger(lo) || !Number.isInteger(hi)) {
        throw new SyntaxError('Numbers must be non-negative integers');
      }
      if (lo > hi) {
        throw new RangeError('Range start must not be greater than end');
      }

      for (let i = lo; i <= hi; i++) {
        result.add(i);
      }
    }
  }

  return Array.from(result).sort((a, b) => a - b);
}

