    i = 0
    n = len(line)

    while i < n:
        if line[i] == '"':
            # Start of a quoted field
            i += 1  # skip opening quote
            field_value = []
            while i < n:
                if line[i] == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        # Escaped quote
                        field_value.append('"')
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        break
                else:
                    field_value.append(line[i])
                    i += 1
            else:
                # End of line without closing quote
                raise ValueError("Unclosed quoted field")

            # After closing quote, must be end of line or a comma
            if i < n and line[i] != ',':
                raise ValueError("Invalid character after quoted field")

            fields.append(''.join(field_value))
        else:
            # Unquoted field: read until comma or end of line
            start = i
            while i < n and line[i] != ',':
                i += 1
            fields.append(line[start:i])

        if i < n and line[i] == ',':
            i += 1

    return fields
