            if count == 0:
                raise ValueError("Count cannot be zero")
            # Check that there is a non-digit character following
            if j >= n or s[j].isdigit():
                raise ValueError("Missing character after count")
            char = s[j]
            result.append(char * count)
            i = j + 1
        else:
            # If we encounter a non-digit at the start or after a group, it's an error
            raise ValueError("Missing count at position {}".format(i))

