function formatBytes(n) {
  if (typeof n !== 'number' || !Number.isFinite(n) || !Number.isInteger(n) || n < 0) {
    if (typeof n !== 'number' || typeof n === 'string') {
      throw new TypeError('n must be a finite number');
    }
