      throw new TypeError('n must be a finite number');
    }
    if (!Number.isInteger(n)) {
      throw new RangeError('n must be an integer');
    }
    if (n < 0) {
      throw new RangeError('n must be non-negative');
    }
    throw new TypeError('n must be a finite number');
  }

  const units = ['B', 'KB', 'MB', 'GB', 'TB'];
  let index = 0;
  let value = n;

  while (index < units.length - 1 && value >= 1024) {
    value /= 1024;
    index++;
  }

  let result;
  if (value % 1 === 0) {
    result = `${Math.round(value)} ${units[index]}`;
  } else {
    result = `${value.toFixed(1)} ${units[index]}`;
  }

  // Handle rounding up case: if rounding results in 1024 and we're not at TB
  if (index < units.length - 1 && result === '1024 KB') {
    result = '1 MB';
  } else if (index < units.length - 2 && result === '1024 MB') {
    result = '1 GB';
  } else if (index < units.length - 3 && result === '1024 GB') {
    result = '1 TB';
  } else if (index < units.length - 4 && result === '1024 TB') {
    // This case shouldn't happen as TB is the max unit
    result = '1024 TB';
  }

  return result;
}

