function expandRanges(spec) {
  if (typeof spec !== 'string') {
    throw new TypeError('spec must be a string');
  }

  const parts = spec.split(',');
  const result = new Set();

  for (const part of parts) {
    const trimmed = part.trim();
    if (trimmed === '') {
      // Empty part due to leading/trailing comma or consecutive commas
      throw new SyntaxError('Invalid range specification: empty part');
    }

    if (trimmed === '-') {
      throw new SyntaxError('Invalid range specification: missing numbers');
    }

    const dashes = trimmed.split('-');
    if (dashes.length === 1) {
      // Single number
      const numStr = dashes[0];
      if (!/^\d+$/.test(numStr)) {
        throw new SyntaxError('Invalid range specification: not a valid number');
      }
      const num = parseInt(numStr, 10);
      if (num < 0) {
        throw new SyntaxError('Invalid range specification: negative number not allowed');
      }
      result.add(num);
    } else if (dashes.length === 2) {
      const startStr = dashes[0];
      const endStr = dashes[1];

      if (!/^\d+$/.test(startStr) || !/^\d+$/.test(endStr)) {
        throw new SyntaxError('Invalid range specification: not a valid number');
      }

      const start = parseInt(startStr, 10);
      const end = parseInt(endStr, 10);

      if (start > end) {
        throw new RangeError('Start of range must not be greater than end');
      }

      for (let i = start; i <= end; i++) {
        result.add(i);
      }
    } else {
      // More than one dash
      throw new SyntaxError('Invalid range specification: too many dashes');
    }
  }

  const sorted = Array.from(result);
  sorted.sort((a, b) => a - b);
  return sorted;
}

