    i = 0
    n = len(s)

    while i < n:
        # Parse the count (digits)
        j = i
        while j < n and s[j].isdigit():
            j += 1

        if j == i:
            # No digit found at the start of a group -> invalid
            raise ValueError("Missing count or invalid format")

        count_str = s[i:j]
        count = int(count_str)

        if count == 0:
            raise ValueError("Count must be at least 1")

        # We need a character after the digits
        if j == n or s[j].isdigit():
            raise ValueError("Missing character after count or trailing digits")

        char = s[j]
        result.append(char * count)
        i = j + 1

    return "".join(result)
