function expandRanges(spec) {
  if (typeof spec !== 'string') {
    throw new TypeError('spec must be a string');
  }

  const parts = spec.split(',');
  const result = new Set();

  for (const part of parts) {
    const trimmed = part.trim();
    if (trimmed === '') {
      throw new SyntaxError('Empty part in specification');
    }

    const partsCount = trimmed.split('-');
    if (partsCount.length > 2) {
      throw new SyntaxError(`Invalid range format: ${part}`);
    }

    if (partsCount.length === 1) {
      // It's a single number
      const numStr = partsCount[0];
      const num = Number(numStr);
      if (!/^\d+$/.test(numStr)) {
        throw new SyntaxError(`Invalid number format: ${part}`);
      }
      result.add(num);
    } else {
      // It's a range
      const loStr = partsCount[0];
      const hiStr = partsCount[1];

      if (loStr === '' || hiStr === '') {
        throw new SyntaxError(`Invalid range format: ${part}`);
      }

      if (!/^\d+$/.test(loStr) || !/^\d+$/.test(hiStr)) {
        throw new SyntaxError(`Invalid range format: ${part}`);
      }

      const lo = Number(loStr);
      const hi = Number(hiStr);

      if (lo > hi) {
        throw new RangeError(`Invalid range: start (${lo}) is greater than end (${hi})`);
      }

      for (let i = lo; i <= hi; i++) {
        result.add(i);
      }
    }
  }

  const sorted = Array.from(result);
  sorted.sort((a, b) => a - b);
  return sorted;
}

module.exports = { expandRanges };
