def roman_to_int(s):
    """Convert a canonical Roman numeral string to an integer.

    Valid range: 1..3999.
    Raises ValueError for invalid or non-canonical input.
    Raises TypeError if input is not a string.
    """
    if not isinstance(s, str):
        raise TypeError("Input must be a string")

    if not s:
        raise ValueError("Empty string is not valid")

    valid_chars = set("IVXLCDM")
    if any(c not in valid_chars for c in s):
        raise ValueError("Invalid character in Roman numeral")

    if s != s.upper():
        raise ValueError("Lower-case input is not valid")

    value_map = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50,
        'C': 100, 'D': 500, 'M': 1000
    }

    subtractive_pairs = {
        ('I', 'V'): 4, ('I', 'X'): 9,
        ('X', 'L'): 40, ('X', 'C'): 90,
        ('C', 'D'): 400, ('C', 'M'): 900
    }

    n = len(s)
    result = 0
    i = 0

    while i < n:
        if i + 1 < n:
            pair = (s[i], s[i+1])
            if pair in subtractive_pairs:
                result += subtractive_pairs[pair]
                i += 2
                continue

        char = s[i]
        value = value_map[char]

        # Check for invalid subtractive combinations
        if i + 1 < n:
            next_char = s[i+1]
            next_value = value_map[next_char]
            if value < next_value:
                # This should be handled by subtractive_pairs; if not, it's invalid
                raise ValueError("Non-canonical subtractive combination")

        result += value
        i += 1

    if result < 1 or result > 3999:
        raise ValueError("Result out of valid range 1..3999")

    return result

