def parse_csv_line(line):
    if not isinstance(line, str):
        raise TypeError("line must be a string")

    fields = []
    i = 0
    n = len(line)

    while True:
        if i >= n:
            # End of line
            if len(fields) == 0:
                # Empty line -> one empty field
                fields.append("")
            break

        # Start a new field
        field_start = i
        if line[i] == '"':
            # Quoted field
            i += 1  # consume opening quote
            value_parts = []
            while i < n:
                if line[i] == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        # Escaped quote
                        value_parts.append('"')
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        break
                else:
                    value_parts.append(line[i])
                    i += 1
            else:
                # Reached end without closing quote
                raise ValueError("Unclosed quoted field")

            # After closing quote, must be comma or end of line
            if i < n and line[i] not in (',', '\n'):
                raise ValueError("Invalid character after quoted field")

            fields.append("".join(value_parts))
        else:
            # Unquoted field: read until comma or end
            while i < n and line[i] != ',':
                i += 1
            fields.append(line[field_start:i])

        # Check if there is a comma to continue
        if i < n and line[i] == ',':
            i += 1  # consume comma and continue to next field
        else:
            # End of line
            break

    return fields
