    if not isinstance(s, str):
        raise TypeError("Input must be a string")

    if not s:
        return ""

    result = []
    i = 0
    while i < len(s):
        # Check if we are at a digit
        if not s[i].isdigit():
            raise ValueError("Missing count at position {}".format(i))

        # Parse the number
        j = i
        while j < len(s) and s[j].isdigit():
            j += 1

        count_str = s[i:j]
        count = int(count_str)

        if count == 0:
            raise ValueError("Count cannot be zero")

        # Check if there is a character following the number
        if j >= len(s):
            raise ValueError("Missing character after count")

        char = s[j]
        if char.isdigit():
            raise ValueError("Character cannot be a digit")

        result.append(char * count)
        i = j + 1

    return "".join(result)
