    if (typeof n !== 'number') {
      throw new TypeError('n must be a number');
    }
    if (!Number.isFinite(n)) {
      throw new TypeError('n must be a finite number');
    }
    if (!Number.isInteger(n)) {
      throw new RangeError('n must be an integer');
    }
    if (n < 0) {
      throw new RangeError('n must not be negative');
    }
    throw new TypeError('n must be a finite number');
  }

  const units = ['B', 'KB', 'MB', 'GB', 'TB'];
  let value = n;
  let unitIndex = 0;

  while (unitIndex < units.length - 1 && value >= 1024) {
    value = value / 1024;
    unitIndex++;
  }

  if (value >= 1024 && unitIndex === units.length - 1) {
    value = value / 1024;
    unitIndex++;
    // Since we reached beyond TB, we clamp to TB with the value scaled
    // But per spec: "Values beyond terabytes stay in TB (2^50 bytes is "1024 TB")"
    // So we don't actually move to a new unit, we just format the value in TB
    // The loop condition prevents moving past TB, but if we are at TB and value >= 1024,
    // we should still format it as TB. The spec says "stay in TB".
    // However, the example 2^50 bytes = 1024 TB implies we just output "1024 TB".
    // So we don't increment unitIndex beyond TB, we just format the value as is.
    // The loop above stops at TB (index 4) because unitIndex < 4 is false when unitIndex=4.
    // So value is already in TB.
  }

  // Rounding to 1 decimal place
  const rounded = Math.round(value * 10) / 10;

  // Check if rounding turned it into 1024 and we can move up
  if (rounded >= 1024 && unitIndex < units.length - 1) {
    const nextValue = rounded / 1024;
    if (nextValue < 1024 || unitIndex === units.length - 2) {
      // Move up one unit
      value = nextValue;
