function expandRanges(spec) {
  if (typeof spec !== 'string') {
    throw new TypeError('spec must be a string');
  }

  const parts = spec.split(',');
  const result = new Set();

  for (const part of parts) {
    const trimmed = part.trim();
    if (trimmed === '') {
      throw new SyntaxError('Invalid range specification: empty part');
    }

    const dashCount = (trimmed.match(/-/g) || []).length;
    if (dashCount === 0) {
      const num = Number(trimmed);
      if (!Number.isFinite(num) || num < 0 || !Number.isInteger(num)) {
        throw new SyntaxError('Invalid range specification: invalid number');
      }
      result.add(num);
    } else if (dashCount === 1) {
      const [loStr, hiStr] = trimmed.split('-');
      if (loStr === '' || hiStr === '') {
        throw new SyntaxError('Invalid range specification: missing start or end in range');
      }
      const lo = Number(loStr);
      const hi = Number(hiStr);
      if (!Number.isFinite(lo) || !Number.isFinite(hi)) {
        throw new SyntaxError('Invalid range specification: invalid number');
      }
      if (lo < 0 || hi < 0 || !Number.isInteger(lo) || !Number.isInteger(hi)) {
        throw new SyntaxError('Invalid range specification: non-integer or negative number');
      }
      if (lo > hi) {
        throw new RangeError('Range start must not be greater than end');
      }
      for (let i = lo; i <= hi; i++) {
        result.add(i);
      }
    } else {
      throw new SyntaxError('Invalid range specification: too many dashes');
    }
  }

  const sorted = Array.from(result).sort((a, b) => a - b);
  return sorted;
}

