def parse_csv_line(line):
    if not isinstance(line, str):
        raise TypeError("line must be a string")

    fields = []
    i = 0
    n = len(line)

    while i <= n:
        if i == n:
            # End of line
            if len(fields) == 0:
                fields.append("")
            break

        if line[i] == '"':
            # Start of quoted field
            i += 1
            field_value = []
            while i < n:
                if line[i] == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        # Escaped quote
                        field_value.append('"')
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        if i == n:
                            # End of line after closing quote - valid
                            break
                        elif line[i] == ',':
                            # Comma follows, valid
                            i += 1
                            break
                        else:
                            # Anything else after closing quote is an error
                            raise ValueError("Expected comma or end of line after quoted field")
                else:
                    field_value.append(line[i])
                    i += 1
            else:
                # Loop finished without break -> end of string reached without closing quote
                raise ValueError("Unclosed quoted field")

            fields.append("".join(field_value))
        else:
            # Unquoted field: read until comma or end of line
            start = i
            while i < n and line[i] != ',':
                i += 1
            fields.append(line[start:i])
            if i < n and line[i] == ',':
                i += 1
            # else we are at end of line, loop will handle it

    return fields
