def spiral_order(matrix: List[List[Any]]) -> List[Any]:
    if not matrix:
        return []

    row_len = len(matrix[0])
    for row in matrix:
        if len(row) != row_len:
            raise ValueError("All rows must have the same length")

    if row_len == 0:
        return []

    result = []
    top, bottom = 0, len(matrix) - 1
    left, right = 0, row_len - 1

    while top <= bottom and left <= right:
        # Traverse right along the top row
        for col in range(left, right + 1):
            result.append(matrix[top][col])
        top += 1

        # Traverse down along the right column
        for row in range(top, bottom + 1):
            result.append(matrix[row][right])
        right -= 1

        # Traverse left along the bottom row, if we still have rows to traverse
        if top <= bottom:
            for col in range(right, left - 1, -1):
                result.append(matrix[bottom][col])
            bottom -= 1

        # Traverse up along the left column, if we still have columns to traverse
        if left <= right:
            for row in range(bottom, top - 1, -1):
                result.append(matrix[row][left])
            left += 1

    return result
