function expandRanges(spec) {
  if (typeof spec !== 'string') {
    throw new TypeError('spec must be a string');
  }

  const parts = spec.split(',');
  const result = new Set();

  for (const part of parts) {
    const trimmed = part.trim();
    if (trimmed === '') {
      throw new SyntaxError('Malformed part: empty part');
    }

    const dashes = trimmed.split('-');
    if (dashes.length === 1) {
      // Single number
      const numStr = dashes[0];
      if (!/^\d+$/.test(numStr)) {
        throw new SyntaxError(`Malformed part: '${part}'`);
      }
      const num = parseInt(numStr, 10);
      result.add(num);
    } else if (dashes.length === 2) {
      const [loStr, hiStr] = dashes;
      if (!/^\d+$/.test(loStr) || !/^\d+$/.test(hiStr)) {
        throw new SyntaxError(`Malformed part: '${part}'`);
      }
      const lo = parseInt(loStr, 10);
      const hi = parseInt(hiStr, 10);
      if (lo > hi) {
        throw new RangeError(`Range start greater than end in '${part}'`);
      }
      for (let i = lo; i <= hi; i++) {
        result.add(i);
      }
    } else {
      throw new SyntaxError(`Malformed part: '${part}'`);
    }
  }

  const sorted = Array.from(result).sort((a, b) => a - b);
  return sorted;
}

