import re

def compare_versions(a, b):
    """
    Compare two Semantic Versioning 2.0.0 strings.

    Returns:
        -1 if a < b
         0 if a == b
         1 if a > b

    Raises:
        ValueError if either string is not a valid version.
    """
    def parse_version(version_str):
        # Regex for SemVer 2.0.0
        # ^v is not allowed, so we match the format strictly
        # MAJOR.MINOR.PATCH(-PRERELEASE)(+BUILD)
        pattern = r'^(\d+)\.(\d+)\.(\d+)(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?(?:\+[0-9A-Za-z-]+)?$'

        match = re.match(pattern, version_str)
        if not match:
            raise ValueError(f"Invalid version string: {version_str}")

        major = int(match.group(1))
        minor = int(match.group(2))
        patch = int(match.group(3))
        prerelease_str = match.group(4)

        prerelease = None
        if prerelease_str is not None:
            # Validate prerelease identifiers
            # Must not be empty (regex ensures non-empty groups, but check if the whole thing is empty logic handled by regex)
            # The regex ensures at least one identifier if prerelease_str is present.
            # We need to validate internal structure: no empty identifiers, no leading zeros in numeric ones.
            identifiers = prerelease_str.split('.')
            for ident in identifiers:
                if not ident:
                    raise ValueError(f"Empty identifier in prerelease: {version_str}")
                if ident.isdigit() and (len(ident) > 1 and ident[0] == '0'):
                    raise ValueError(f"Leading zero in numeric prerelease identifier: {ident}")
            prerelease = identifiers

        return (major, minor, patch), prerelease

    def compare_prerelease(a_pre, b_pre):
        # If one is None and the other is not, the one with prerelease is lower
        if a_pre is None and b_pre is None:
            return 0
        if a_pre is None:
            return 1  # a has no prerelease, so a > b
        if b_pre is None:
            return -1 # b has no prerelease, so a < b

        # Compare identifier by identifier
        for i in range(min(len(a_pre), len(b_pre))):
            a_ident = a_pre[i]
            b_ident = b_pre[i]

            a_is_num = a_ident.isdigit()
            b_is_num = b_ident.isdigit()

            if a_is_num and b_is_num:
                # Both numeric: compare numerically
                a_val = int(a_ident)
                b_val = int(b_ident)
                if a_val < b_val:
                    return -1
                elif a_val > b_val:
                    return 1
            elif a_is_num and not b_is_num:
                # Numeric has lower precedence than non-numeric
                return -1
            elif not a_is_num and b_is_num:
                # Non-numeric has higher precedence than numeric
                return 1
            else:
                # Both non-numeric: compare lexically
                if a_ident < b_ident:
                    return -1
                elif a_ident > b_ident:
                    return 1

        # If we get here, shared identifiers are equal
        # The one with more identifiers has higher precedence
        if len(a_pre) < len(b_pre):
            return -1
        elif len(a_pre) > len(b_pre):
            return 1
        return 0

    # Parse versions
    try:
        a_core, a_pre = parse_version(a)
        b_core, b_pre = parse_version(b)
    except ValueError:
        raise ValueError("Invalid version string")

    # Compare core version parts
    if a_core[0] != b_core[0]:
        return -1 if a_core[0] < b_core[0] else 1
    if a_core[1] != b_core[1]:
        return -1 if a_core[1] < b_core[1] else 1
    if a_core[2] != b_core[2]:
        return -1 if a_core[2] < b_core[2] else 1

    # Core versions are equal, compare prerelease
    return compare_prerelease(a_pre, b_pre)

