function expandRanges(spec) {
  if (typeof spec !== 'string') {
    throw new TypeError('spec must be a string');
  }

  const parts = spec.split(',');
  const result = new Set();

  for (const part of parts) {
    const trimmed = part.trim();
    if (trimmed === '') {
      continue;
    }

    if (trimmed === '') {
      // This case is already handled above, but kept for clarity
      continue;
    }

    if (trimmed.includes('-')) {
      const dashCount = (trimmed.match(/-/g) || []).length;
      if (dashCount !== 1) {
        throw new SyntaxError(`Invalid part: ${part}`);
      }

      const [loStr, hiStr] = trimmed.split('-');
      if (loStr === '' || hiStr === '') {
        throw new SyntaxError(`Invalid part: ${part}`);
      }

      const lo = parseInt(loStr, 10);
      const hi = parseInt(hiStr, 10);

      if (isNaN(lo) || isNaN(hi)) {
        throw new SyntaxError(`Invalid part: ${part}`);
      }

      if (loStr !== String(lo) || hiStr !== String(hi)) {
        throw new SyntaxError(`Invalid part: ${part}`);
      }

      if (lo < 0 || hi < 0) {
        throw new SyntaxError(`Invalid part: ${part}`);
      }

      if (lo > hi) {
        throw new RangeError(`Range start is greater than end: ${part}`);
      }

      for (let i = lo; i <= hi; i++) {
        result.add(i);
      }
    } else {
      if (!/^\d+$/.test(trimmed)) {
        throw new SyntaxError(`Invalid part: ${part}`);
      }

      const num = parseInt(trimmed, 10);
      if (isNaN(num)) {
        throw new SyntaxError(`Invalid part: ${part}`);
      }
      if (trimmed !== String(num)) {
        throw new SyntaxError(`Invalid part: ${part}`);
      }
      result.add(num);
    }
  }

  return Array.from(result).sort((a, b) => a - b);
}

