def rle_encode(s):
    if not isinstance(s, str):
        raise TypeError("Input must be a string")

    if any(c.isdigit() for c in s):
        raise ValueError("Input must not contain any digit character")

    if not s:
        return ""

    result = []
    count = 1

    for i in range(1, len(s)):
        if s[i] == s[i-1]:
            count += 1
        else:
            result.append(f"{count}{s[i-1]}")
            count = 1

    result.append(f"{count}{s[-1]}")
    return "".join(result)


def rle_decode(s):
    if not isinstance(s, str):
        raise TypeError("Input must be a string")

    if not s:
        return ""

    result = []
    i = 0

    while i < len(s):
        # Parse the count (one or more digits)
        count_start = i
        while i < len(s) and s[i].isdigit():
            i += 1

        # Check if we found any digits
        if i == count_start:
            raise ValueError("Missing count")

        # Check if there's a character after the digits
        if i >= len(s):
            raise ValueError("Trailing digits with no character")

        # Parse the count value
        count_str = s[count_start:i]
        count = int(count_str)

        # Check if count is at least 1
        if count == 0:
            raise ValueError("Count must be at least 1")

        # Get the character
        char = s[i]
        i += 1

        # Append the character 'count' times
        result.append(char * count)

    return "".join(result)
