      this._listeners.set(event, []);
    }
    this._listeners.get(event).push({ fn, once: false });
    return this;
  }

  once(event, fn) {
    if (typeof fn !== 'function') {
      throw new TypeError('fn must be a function');
    }
    if (!this._listeners.has(event)) {
      this._listeners.set(event, []);
    }
    this._listeners.get(event).push({ fn, once: true });
    return this;
  }

  off(event, fn) {
    if (!this._listeners.has(event)) {
      return this;
    }
    const listeners = this._listeners.get(event);
    const initialLength = listeners.length;
    this._listeners.set(event, listeners.filter(item => item.fn !== fn));
    return this;
  }

  emit(event, ...args) {
    if (!this._listeners.has(event)) {
      return false;
    }

    const listeners = this._listeners.get(event);
    if (listeners.length === 0) {
      return false;
    }

    const toRemove = [];
    let called = false;

    for (let i = 0; i < listeners.length; i++) {
      const item = listeners[i];
      called = true;

      if (item.once) {
        toRemove.push(item);
      }

      item.fn.call(this, ...args);
    }

    if (toRemove.length > 0) {
      this._listeners.set(event, listeners.filter(item => !toRemove.includes(item)));
    }

    return called;
  }

  listenerCount(event) {
    if (!this._listeners.has(event)) {
      return 0;
    }
    return this._listeners.get(event).length;
  }
}

