function expandRanges(spec) {
  if (typeof spec !== 'string') {
    throw new TypeError('spec must be a string');
  }

  const parts = spec.split(',');
  const result = new Set();

  for (const part of parts) {
    const trimmed = part.trim();
    if (trimmed.length === 0) {
      // Empty part due to leading/trailing comma or consecutive commas
      throw new SyntaxError('Malformed part: empty part detected');
    }

    if (trimmed.includes('-')) {
      const dashes = trimmed.split('-');
      if (dashes.length !== 2) {
        // More than one dash or invalid structure
        throw new SyntaxError(`Malformed part: ${trimmed}`);
      }

      const loStr = dashes[0];
      const hiStr = dashes[1];

      if (loStr.length === 0 || hiStr.length === 0) {
        // Missing start or end
        throw new SyntaxError(`Malformed part: ${trimmed}`);
      }

      const lo = parseInt(loStr, 10);
      const hi = parseInt(hiStr, 10);

      if (isNaN(lo) || isNaN(hi)) {
        throw new SyntaxError(`Malformed part: ${trimmed}`);
      }

      if (lo > hi) {
        throw new RangeError(`Range start greater than end: ${lo}-${hi}`);
      }

      for (let i = lo; i <= hi; i++) {
        result.add(i);
      }
    } else {
      // Single number
      const num = parseInt(trimmed, 10);
      if (isNaN(num)) {
        throw new SyntaxError(`Malformed part: ${trimmed}`);
      }

      // Check for invalid characters like letters, +, -, decimals
      // parseInt stops at the first non-digit, but we must reject if the whole string wasn't a valid integer representation
      if (!/^\d+$/.test(trimmed)) {
        throw new SyntaxError(`Malformed part: ${trimmed}`);
      }

      result.add(num);
    }
  }

  if (result.size === 0) {
    return [];
  }

  const sorted = Array.from(result);
  sorted.sort((a, b) => a - b);
  return sorted;
}

module.exports = { expandRanges };
