function expandRanges(spec) {
  if (typeof spec !== 'string') {
    throw new TypeError('spec must be a string');
  }

  const parts = spec.split(',');
  const result = new Set();

  for (const part of parts) {
    const trimmed = part.trim();
    if (trimmed === '') {
      throw new SyntaxError('Empty part in specification');
    }

    if (trimmed.includes('-')) {
      const dashes = trimmed.split('-');
      if (dashes.length !== 2) {
        throw new SyntaxError('Invalid part with multiple dashes');
      }

      const loStr = dashes[0];
      const hiStr = dashes[1];

      if (loStr === '' || hiStr === '') {
        throw new SyntaxError('Missing number in range');
      }

      const lo = parseInt(loStr, 10);
      const hi = parseInt(hiStr, 10);

      if (isNaN(lo) || isNaN(hi) || !/^\d+$/.test(loStr) || !/^\d+$/.test(hiStr)) {
        throw new SyntaxError('Invalid number in range');
      }

      if (lo > hi) {
        throw new RangeError('Start of range must not be greater than end');
      }

      for (let i = lo; i <= hi; i++) {
        result.add(i);
      }
    } else {
      if (!/^\d+$/.test(trimmed)) {
        throw new SyntaxError('Invalid part');
      }

      const num = parseInt(trimmed, 10);
      result.add(num);
    }
  }

  return Array.from(result).sort((a, b) => a - b);
}

