def parse_csv_line(line):
    if not isinstance(line, str):
        raise TypeError("line must be a string")

    fields = []
    i = 0
    n = len(line)

    while True:
        if i == n:
            # End of line
            if len(fields) == 0 or (len(fields) == 1 and fields[0] == ""):
                # Empty line yields one empty field
                fields = [""]
            break

        if line[i] == '"':
            # Start of a quoted field
            i += 1  # skip opening quote
            field = []
            while i < n:
                if line[i] == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        # Escaped quote
                        field.append('"')
                        i += 2
                    else:
                        # End of quoted field
                        i += 1  # skip closing quote
                        break
                else:
                    field.append(line[i])
                    i += 1
            else:
                # Reached end of line without closing quote
                raise ValueError("Unclosed quoted field")

            # After closing quote, must be comma or end of line
            if i < n and line[i] != ',':
                raise ValueError("Invalid character after quoted field")

            fields.append("".join(field))

            # If not at end, skip comma and continue
            if i < n and line[i] == ',':
                i += 1
        else:
            # Unquoted field: read until comma or end
            start = i
            while i < n and line[i] != ',':
                i += 1
            fields.append(line[start:i])

            # If not at end, skip comma
            if i < n and line[i] == ',':
                i += 1

    return fields
