function expandRanges(spec) {
  if (typeof spec !== 'string') {
    throw new TypeError('spec must be a string');
  }

  const parts = spec.split(',');
  const result = new Set();

  for (const part of parts) {
    const trimmed = part.trim();
    if (trimmed === '') {
      // Empty part means malformed (e.g., "1,,2" or trailing comma)
      throw new SyntaxError('Empty part detected');
    }

    const dashIndex = trimmed.indexOf('-');
    if (dashIndex === -1) {
      // No dash: must be a valid non-negative integer
      const num = Number(trimmed);
      if (!Number.isFinite(num) || trimmed !== String(num)) {
        // Check for invalid formats like "007" -> String(7) is "7", but "007" is valid per spec
        // Re-check: "007" -> Number("007") is 7. String(7) is "7". "007" !== "7", so we need a different check.
        // Spec says leading zeros are allowed. So we should check if it's a valid non-negative integer string.
        // Valid: digits only, possibly with leading zeros, not empty.
        if (!/^\d+$/.test(trimmed)) {
          throw new SyntaxError('Invalid part format');
        }
        const val = parseInt(trimmed, 10);
        if (val < 0) {
          throw new RangeError('Range start must not exceed end');
        }
        result.add(val);
      } else {
        // This path is unreachable if regex check passes, but for safety:
        if (!/^\d+$/.test(trimmed)) {
          throw new SyntaxError('Invalid part format');
        }
        const val = parseInt(trimmed, 10);
        result.add(val);
      }
    } else {
      // Has dash: must be "lo-hi"
      const dashCount = (trimmed.match(/-/g) || []).length;
      if (dashCount !== 1) {
        throw new SyntaxError('Invalid part format');
      }

      const [loStr, hiStr] = trimmed.split('-');
      if (loStr === '' || hiStr === '') {
        throw new SyntaxError('Invalid part format');
      }

      if (!/^\d+$/.test(loStr) || !/^\d+$/.test(hiStr)) {
        throw new SyntaxError('Invalid part format');
      }

      const lo = parseInt(loStr, 10);
      const hi = parseInt(hiStr, 10);

      if (lo > hi) {
        throw new RangeError('Range start must not exceed end');
      }

      for (let i = lo; i <= hi; i++) {
        result.add(i);
      }
    }
  }

  const sorted = Array.from(result);
  sorted.sort((a, b) => a - b);
  return sorted;
