        raise TypeError("Input must be a string")

    if not s:
        return ""

    result = []
    i = 0

    while i < len(s):
        # Try to parse the count (one or more digits)
        start = i
        if not s[i].isdigit():
            raise ValueError("Invalid encoding: missing count or invalid format")

        while i < len(s) and s[i].isdigit():
            i += 1

        if i == start:
            raise ValueError("Invalid encoding: no digits found for count")

        count_str = s[start:i]
        count = int(count_str)

        if count == 0:
            raise ValueError("Invalid encoding: count cannot be zero")

        if i >= len(s) or s[i].isdigit():
            raise ValueError("Invalid encoding: missing character after count")

        char = s[i]
        result.append(char * count)
        i += 1

    return "".join(result)
