def spiral_order(matrix: List[List[Any]]) -> List[Any]:
    if not matrix:
        return []

    # Check if all rows have the same length
    first_len = len(matrix[0])
    if first_len == 0:
        # If the first row is empty, all rows must be empty (as per problem statement)
        # But we already handled empty matrix above. Here we have [[]] or [[], []]
        return []

