  if (typeof dateStr !== 'string') {
    throw new TypeError('dateStr must be a string');
  }

  const pattern = /^(\d{4})-(\d{2})-(\d{2})$/;
  const match = dateStr.match(pattern);

  if (!match) {
    throw new RangeError('dateStr must be in YYYY-MM-DD format');
  }

  if (typeof days !== 'number' || !Number.isInteger(days)) {
    throw new TypeError('days must be an integer');
  }

  const year = parseInt(match[1], 10);
  const month = parseInt(match[2], 10);
  const day = parseInt(match[3], 10);

  if (year < 1 || year > 9999 || month < 1 || month > 12 || day < 1 || day > 31) {
    throw new RangeError('Invalid calendar date');
  }

  // Create a UTC date object
  const date = new Date(Date.UTC(year, month - 1, day));

  if (date.getUTCFullYear() !== year ||
      date.getUTCMonth() !== month - 1 ||
      date.getUTCDate() !== day) {
    throw new RangeError('Invalid calendar date');
  }

  const totalDays = date.getUTCDate() + days;
  const nextDate = new Date(Date.UTC(date.getUTCFullYear(), date.getUTCMonth(), totalDays));

  const resultYear = nextDate.getUTCFullYear();
  const resultMonth = nextDate.getUTCMonth() + 1;
  const resultDay = nextDate.getUTCDate();

  if (resultYear < 1 || resultYear > 9999) {
    throw new RangeError('Resulting year is outside 0001..9999');
  }

  const pad = (n) => String(n).padStart(2, '0');
  const yearStr = String(resultYear).padStart(4, '0');

  return `${yearStr}-${pad(resultMonth)}-${pad(resultDay)}`;
}

