function memoize(fn, keyFn) {
  if (typeof fn !== 'function') {
    throw new TypeError('fn must be a function');
  }

  let cacheKeyFn = keyFn;
  if (cacheKeyFn === undefined) {
    cacheKeyFn = (args) => args[0];
  } else if (typeof cacheKeyFn !== 'function') {
    throw new TypeError('keyFn must be a function if provided');
  }

  const cache = new Map();

  function memoized(...args) {
    const key = cacheKeyFn.apply(this, args);
    if (cache.has(key)) {
      const result = cache.get(key);
      return result;
    }

    let result;
    try {
      result = fn.apply(this, args);
    } catch (error) {
      // If fn throws, do not cache the result and re-throw the error.
      throw error;
    }

    cache.set(key, result);
    return result;
  }

  memoized.clear = function clear() {
    cache.clear();
  };

  return memoized;
}

