function formatTable(rows) {
  if (!Array.isArray(rows)) {
    throw new TypeError('rows must be an array');
  }

  for (let i = 0; i < rows.length; i++) {
    if (!Array.isArray(rows[i])) {
      throw new TypeError('rows must be an array of arrays');
    }
  }

  if (rows.length === 0) {
    return '';
  }

  // Convert cells to strings, treating null and undefined as empty strings
  const convertedRows = rows.map(row =>
    row.map(cell => (cell === null || cell === undefined ? '' : String(cell)))
  );

  // Find the maximum number of columns (width of widest row)
  const maxColumns = Math.max(...convertedRows.map(row => row.length));

  // Calculate the width of each column
  const colWidths = new Array(maxColumns).fill(0);
  for (const row of convertedRows) {
    for (let i = 0; i < row.length; i++) {
      colWidths[i] = Math.max(colWidths[i], row[i].length);
    }
  }

  // Build the output lines
  const lines = convertedRows.map(row => {
    const cells = [];
    for (let i = 0; i < maxColumns; i++) {
      const cell = row[i] !== undefined ? row[i] : '';
      // Pad on the right to column width
      const padded = cell.padEnd(colWidths[i]);
      cells.push(padded);
    }
    // Join with " | "
    const joined = cells.join(' | ');
    // Remove trailing spaces from the end of the line
    return joined.trimEnd();
  });

  return lines.join('\n');
}

