def is_balanced(code):
    stack = []
    i = 0
    n = len(code)

    while i < n:
        ch = code[i]

        if ch == '"':
            # Enter string literal
            i += 1
            while i < n:
                c = code[i]
                if c == '"':
                    # End of string
                    i += 1
                    break
                elif c == '\\' and i + 1 < n:
                    # Escaped character, skip both
                    i += 2
                else:
                    i += 1
            else:
                # String never closed
                return False
            continue

        if ch in '([{':
            stack.append(ch)
        elif ch == ')':
            if not stack or stack[-1] != '(':
                return False
            stack.pop()
        elif ch == ']':
            if not stack or stack[-1] != '[':
                return False
            stack.pop()
        elif ch == '}':
            if not stack or stack[-1] != '{':
                return False
            stack.pop()

        i += 1

    return len(stack) == 0
