def wrap_text(text, width):
    if not isinstance(width, int):
        raise TypeError("width must be an integer")
    if width < 1:
        raise ValueError("width must be at least 1")

    if not isinstance(text, str):
        raise TypeError("text must be a string")

    words = text.split()
    if not words:
        return []

    lines = []
    current_line = []

    for word in words:
        # Check if the word can be added to the current line
        if current_line:
            # Check if adding the word exceeds width
            if len(' '.join(current_line)) + 1 + len(word) <= width:
                current_line.append(word)
            else:
                # Current line is full, save it and start a new one
                lines.append(' '.join(current_line))
                current_line = [word]
        else:
            # First word or new line
            if len(word) <= width:
                current_line.append(word)
            else:
                # Word longer than width, goes on its own line
                lines.append(word)
                current_line = []

    # Add the last line if it has words
    if current_line:
        lines.append(' '.join(current_line))

    return lines
