def is_balanced(code):
    stack = []
    i = 0
    n = len(code)

    while i < n:
        ch = code[i]

        if ch == '"':
            # Start of a string literal
            i += 1
            while i < n:
                c = code[i]
                if c == '"':
                    # End of string
                    i += 1
                    break
                elif c == '\\' and i + 1 < n:
                    # Escaped character, skip both backslash and next char
                    i += 2
                else:
                    i += 1
            else:
                # Reached end without finding closing quote -> unbalanced string
                return False
            continue

        if ch in '([{':
            stack.append(ch)
        elif ch in ')]}':
            if not stack:
                return False
            top = stack.pop()
            if ch == ')' and top != '(':
                return False
            if ch == ']' and top != '[':
                return False
            if ch == '}' and top != '{':
                return False

        i += 1

    return len(stack) == 0
