def wrap_text(text, width):
    if not isinstance(width, int):
        raise TypeError("width must be an integer")
    if width < 1:
        raise ValueError("width must be at least 1")

    words = text.split()
    if not words:
        return []

    lines = []
    current_line = []
    current_len = 0

    for word in words:
        word_len = len(word)
        if word_len > width:
            # Word too long to fit on any line; it goes on its own line
            if current_line:
                lines.append(" ".join(current_line))
                current_line = []
                current_len = 0
            lines.append(word)
            continue

        if current_line:
            # Need a space before adding the word
            if current_len + 1 + word_len <= width:
                current_line.append(word)
                current_len += 1 + word_len
            else:
                lines.append(" ".join(current_line))
                current_line = [word]
                current_len = word_len
        else:
            # First word on an empty line
            current_line = [word]
            current_len = word_len

    if current_line:
        lines.append(" ".join(current_line))

    return lines
