import re

def to_24h(text):
    if not isinstance(text, str):
        raise TypeError("text must be a string")

    text = text.strip()
    if not text:
        raise ValueError("empty text")

    pattern = re.compile(
        r'^(?P<hour>\d{1,2}):(?P<minute>\d{2})\s*(?P<ampm>[APap][Mm])?$',
        re.IGNORECASE
    )

    match = pattern.match(text)
    if not match:
        raise ValueError("invalid format")

    hour = int(match.group('hour'))
    minute = int(match.group('minute'))
    ampm = match.group('ampm')

    if hour == 0 or hour > 12:
        raise ValueError("hour must be between 1 and 12")

    if minute > 59:
        raise ValueError("minutes must be between 00 and 59")

    if not ampm or ampm.upper() not in ('AM', 'PM'):
        raise ValueError("missing or invalid AM/PM")

    ampm_upper = ampm.upper()

    if ampm_upper == 'AM':
        if hour == 12:
            hour = 0
    else:  # PM
        if hour != 12:
            hour += 12

    return f"{hour:02d}:{minute:02d}"
