function addDays(dateStr, days) {
  if (typeof dateStr !== 'string') {
    throw new TypeError('dateStr must be a string');
  }
  if (!Number.isInteger(days)) {
    throw new TypeError('days must be an integer');
  }

  // Validate exact format: YYYY-MM-DD (four digits, dash, two digits, dash, two digits)
  if (!/^\d{4}-\d{2}-\d{2}$/.test(dateStr)) {
    throw new RangeError('dateStr must be in YYYY-MM-DD format');
  }

  const [yearStr, monthStr, dayStr] = dateStr.split('-');
  const year = parseInt(yearStr, 10);
  const month = parseInt(monthStr, 10);
  const day = parseInt(dayStr, 10);

  // Validate ranges for month and day (basic sanity before creating Date)
  if (month < 1 || month > 12) {
    throw new RangeError('Invalid month in dateStr');
  }
  if (day < 1 || day > 31) {
    throw new RangeError('Invalid day in dateStr');
  }

  // Create UTC date: month is 0-indexed for Date constructor
  const date = new Date(Date.UTC(year, month - 1, day));

  // Check if the date was invalid (e.g., Feb 30 becomes March 2)
  if (date.getUTCFullYear() !== year ||
      date.getUTCMonth() !== month - 1 ||
      date.getUTCDate() !== day) {
    throw new RangeError('dateStr is not a valid calendar date');
  }

  // Add days using UTC time
  const msPerDay = 24 * 60 * 60 * 1000;
  const targetDate = new Date(date.getTime() + days * msPerDay);

  const resultYear = targetDate.getUTCFullYear();
  const resultMonth = targetDate.getUTCMonth() + 1;
  const resultDay = targetDate.getUTCDate();

  // Validate year range 0001..9999
  if (resultYear < 1 || resultYear > 9999) {
    throw new RangeError('Year out of range 0001..9999');
