    let key;
    if (keyFn !== undefined) {
      key = keyFn.apply(this, arguments);
    } else {
      key = arguments[0];
    }

    if (cache.has(key)) {
      const cachedValue = cache.get(key);
      return cachedValue;
    }

    let result;
    try {
      result = fn.apply(this, arguments);
    } catch (error) {
      // Do not cache on error, re-throw
      throw error;
    }

    cache.set(key, result);
    return result;
  };

  memoized.clear = function() {
    cache.clear();
  };

  return memoized;
}

