  const paddedRows = rows.map(row =>
    row.map(cell => {
      if (cell === null || cell === undefined) {
        return '';
      }
      return String(cell);
    })
  );

  // Calculate column widths
  let maxColumns = 0;
  for (const row of paddedRows) {
    if (row.length > maxColumns) {
      maxColumns = row.length;
    }
  }

  // Ensure all rows have the same length by padding with empty strings
  const normalizedRows = paddedRows.map(row => {
    const extended = row.slice();
    while (extended.length < maxColumns) {
      extended.push('');
    }
    return extended;
  });

  // Calculate widths for each column
  const columnWidths = new Array(maxColumns).fill(0);
  for (const row of normalizedRows) {
    for (let i = 0; i < row.length; i++) {
      const len = row[i].length;
      if (len > columnWidths[i]) {
        columnWidths[i] = len;
      }
    }
  }

  // Build output lines
  const lines = [];
  for (const row of normalizedRows) {
    const cells = [];
    for (let i = 0; i < row.length; i++) {
      const content = row[i];
      const width = columnWidths[i];
      const padding = ' '.repeat(width - content.length);
      cells.push(content + padding);
    }
    // Join with " | " and trim trailing spaces from the end of the line
    const line = cells.join(' | ');
    lines.push(line.trimEnd());
  }

  return lines.join('\n');
}

