def is_balanced(code):
    stack = []
    i = 0
    n = len(code)

    while i < n:
        ch = code[i]

        if ch == '"':
            # Start of a string literal
            i += 1
            while i < n:
                if code[i] == '"':
                    # End of string
                    i += 1
                    break
                elif code[i] == '\\' and i + 1 < n:
                    # Escaped character, skip both
                    i += 2
                else:
                    i += 1
            else:
                # Reached end without closing quote
                return False
        elif ch in '({[':
            stack.append(ch)
            i += 1
        elif ch in ')}]':
            if not stack:
                return False
            top = stack.pop()
            if ch == ')' and top != '(':
                return False
            if ch == '}' and top != '{':
                return False
            if ch == ']' and top != '[':
                return False
            i += 1
        else:
            i += 1

    return len(stack) == 0
