def wrap_text(text: str, width: int) -> List[str]:
    if not isinstance(width, int) or isinstance(width, bool):
        raise TypeError("width must be an int")
    if width < 1:
        raise ValueError("width must be at least 1")

    if not text:
        return []

    words = text.split()
    lines = []

    if not words:
        return []

    current_line = []
    current_length = 0

    for word in words:
        word_len = len(word)

        if word_len > width:
            # Word longer than width: start a new line with just this word
            if current_line:
                lines.append(" ".join(current_line))
                current_line = []
                current_length = 0
            lines.append(word)
            continue

        if current_length == 0:
            # First word on a new line
            current_line.append(word)
            current_length = word_len
        elif current_length + 1 + word_len <= width:
            # Fits on current line
            current_line.append(word)
            current_length += 1 + word_len
        else:
            # Doesn't fit, save current line and start a new one
            lines.append(" ".join(current_line))
            current_line = [word]
            current_length = word_len

    if current_line:
        lines.append(" ".join(current_line))

    return lines

