def is_balanced(code):
    stack = []
    i = 0
    n = len(code)

    while i < n:
        ch = code[i]

        if ch == '"':
            # Start of a string literal
            i += 1
            while i < n:
                c = code[i]
                if c == '\\':
                    # Skip the escaped character
                    i += 2
                    continue
                if c == '"':
                    # End of string literal
                    i += 1
                    break
                i += 1
            else:
                # String never closed
                return False
            continue

        if ch in '([{':
            stack.append(ch)
        elif ch in ')]}':
            if not stack:
                return False
            top = stack.pop()
            if ch == ')' and top != '(':
                return False
            if ch == ']' and top != '[':
                return False
            if ch == '}' and top != '{':
                return False

        i += 1

    return len(stack) == 0
