def wrap_text(text, width):
    if not isinstance(width, int):
        raise TypeError("width must be an integer")
    if width < 1:
        raise ValueError("width must be at least 1")

    words = text.split()
    if not words:
        return []

    lines = []
    current_line = []

    for word in words:
        if len(word) > width:
            # Word longer than width: flush current line if any, then add word alone
            if current_line:
                lines.append(" ".join(current_line))
                current_line = []
            lines.append(word)
        else:
            # Try to add word to current line
            if not current_line:
                current_line.append(word)
            else:
                # Check if adding word exceeds width (plus one space)
                if len(" ".join(current_line)) + 1 + len(word) <= width:
                    current_line.append(word)
                else:
                    lines.append(" ".join(current_line))
                    current_line = [word]

    if current_line:
        lines.append(" ".join(current_line))

