def search_rotated(nums, target):
    left = 0
    right = len(nums) - 1

    while left <= right:
        mid = (left + right) // 2
        mid_val = nums[mid]

        if mid_val == target:
            return mid

        # Determine which side is sorted
        if nums[left] <= mid_val:
            # Left side is sorted
            if nums[left] <= target < mid_val:
                right = mid - 1
            else:
                left = mid + 1
        else:
            # Right side is sorted
            if mid_val < target <= nums[right]:
                left = mid + 1
            else:
                right = mid - 1

    return -1
