def wrap_text(text, width):
    if not isinstance(width, int) or isinstance(width, bool):
        raise TypeError("width must be an int")
    if width < 1:
        raise ValueError("width must be at least 1")

    if not text:
        return []

    words = text.split()
    if not words:
        return []

    lines = []
    current_line = []
    current_length = 0

    for word in words:
        word_len = len(word)
        if word_len > width:
            # Word too long: finish current line if any, then add word as its own line
            if current_line:
                lines.append(" ".join(current_line))
                current_line = []
                current_length = 0
            lines.append(word)
        else:
            # Try to fit the word on the current line
            if current_length == 0:
                current_line.append(word)
                current_length = word_len
            elif current_length + 1 + word_len <= width:
                current_line.append(word)
                current_length += 1 + word_len
            else:
                # Finish current line and start a new one with this word
                lines.append(" ".join(current_line))
                current_line = [word]
                current_length = word_len

    if current_line:
        lines.append(" ".join(current_line))

    return lines
