def search_rotated(nums, target):
    low = 0
    high = len(nums) - 1

    while low <= high:
        mid = (low + high) // 2
        mid_val = nums[mid]

        if mid_val == target:
            return mid

        # Determine which side is sorted
        if nums[low] <= mid_val:
            # Left side is sorted
            if nums[low] <= target < mid_val:
                high = mid - 1
            else:
                low = mid + 1
        else:
            # Right side is sorted
            if mid_val < target <= nums[high]:
                low = mid + 1
            else:
                high = mid - 1

    return -1
