function addDays(dateStr, days) {
  if (typeof dateStr !== 'string') {
    throw new TypeError('dateStr must be a string');
  }
  if (!Number.isInteger(days)) {
    throw new TypeError('days must be an integer');
  }

  const pattern = /^(\d{4})-(\d{2})-(\d{2})$/;
  const match = dateStr.match(pattern);
  if (!match) {
    throw new RangeError('dateStr must be in YYYY-MM-DD format');
  }

  let year = parseInt(match[1], 10);
  const month = parseInt(match[2], 10);
  const day = parseInt(match[3], 10);

  if (year < 1 || year > 9999 || month < 1 || month > 12 || day < 1 || day > 31) {
    throw new RangeError('dateStr must be a valid calendar date');
  }

  const date = new Date(Date.UTC(year, month - 1, day));

  if (date.getUTCMonth() !== month - 1 || date.getUTCDate() !== day) {
    throw new RangeError('dateStr must be a valid calendar date');
  }

  date.setUTCDate(date.getUTCDate() + days);

  const newYear = date.getUTCFullYear();
  const newMonth = date.getUTCMonth() + 1;
  const newDay = date.getUTCDate();

  if (newYear < 1 || newYear > 9999) {
    throw new RangeError('result year must be between 0001 and 9999');
  }

  const yearStr = newYear.toString().padStart(4, '0');
  const monthStr = newMonth.toString().padStart(2, '0');
  const dayStr = newDay.toString().padStart(2, '0');

  return `${yearStr}-${monthStr}-${dayStr}`;
}

