    const char = firstCodePoints[i];
    for (let j = 1; j < n; j++) {
      const s = strs[j];
      const sCodePoints = toCodePoints(s);
      if (i >= sCodePoints.length || sCodePoints[i] !== char) {
        return first.slice(0, i);
      }
    }
  }

  return first;
}

