def maze_steps(grid):
    if not grid:
        raise ValueError("Grid must not be empty")

    row_len = len(grid[0])
    if any(len(row) != row_len for row in grid):
        raise ValueError("All rows must have the same length")

    valid_chars = {'S', 'E', '#', '.'}
    start = None
    end = None
    count_s = 0
    count_e = 0

    for r, row in enumerate(grid):
        for c, cell in enumerate(row):
            if cell not in valid_chars:
                raise ValueError(f"Invalid character: {cell}")
            if cell == 'S':
                count_s += 1
                start = (r, c)
            elif cell == 'E':
                count_e += 1
                end = (r, c)

    if count_s != 1:
        raise ValueError("There must be exactly one 'S'")
    if count_e != 1:
        raise ValueError("There must be exactly one 'E'")

    if start is None or end is None:
        raise ValueError("Start and Exit must be present")

    if start == end:
        return 0

    rows = len(grid)
    cols = len(grid[0])

    queue = deque([(start[0], start[1], 0)])
    visited = set([start])

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    while queue:
        r, c, dist = queue.popleft()

        for dr, dc in directions:
            nr, nc = r + dr, c + dc

            if 0 <= nr < rows and 0 <= nc < cols:
                if (nr, nc) not in visited:
                    cell = grid[nr][nc]
                    if cell in ('.', 'S', 'E'):
                        if (nr, nc) == end:
                            return dist + 1
                        visited.add((nr, nc))
                        queue.append((nr, nc, dist + 1))

    return -1
