                if start is not None:
                    raise ValueError("There must be exactly one 'S'")
                start = (r, c)
            elif char == 'E':
                if end is not None:
                    raise ValueError("There must be exactly one 'E'")
                end = (r, c)

    if start is None:
        raise ValueError("There must be exactly one 'S'")
    if end is None:
        raise ValueError("There must be exactly one 'E'")

    rows = len(grid)
    cols = row_len

    visited = [[False] * cols for _ in range(rows)]
    queue = deque([(start[0], start[1], 0)])
    visited[start[0]][start[1]] = True

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

