      throw new TypeError('Array must contain only strings');
    }
  }

  // Handle empty string in array
  if (strs.some(s => s.length === 0)) {
    return '';
  }

  const n = strs.length;
  const first = strs[0];

  // We'll iterate code points (Unicode) to ensure we don't break surrogate pairs
  let result = '';
  let i = 0;

  while (true) {
    // Get the next code point in the first string
    // Using Array.from to properly handle surrogate pairs
    const firstCodePoints = Array.from(first);
    if (i >= firstCodePoints.length) break;

    const char = firstCodePoints[i];

    // Check all other strings at position i
    let allMatch = true;
    for (let j = 1; j < n; j++) {
      const otherCodePoints = Array.from(strs[j]);
      if (i >= otherCodePoints.length || otherCodePoints[i] !== char) {
        allMatch = false;
        break;
      }
    }

    if (!allMatch) break;

    result += char;
    i++;
  }

  return result;
