    row_length = len(grid[0])
    for i, row in enumerate(grid):
        if len(row) != row_length:
            raise ValueError("All rows must have the same length")

        # Validate characters
        for j, char in enumerate(row):
            if char not in {'S', 'E', '#', '.'}:
                raise ValueError(f"Invalid character '{char}' at row {i}, column {j}")

    # Count S and E
    start = None
    end = None
    s_count = 0
    e_count = 0

    for i, row in enumerate(grid):
        for j, char in enumerate(row):
            if char == 'S':
                s_count += 1
                start = (i, j)
            elif char == 'E':
                e_count += 1
                end = (i, j)

    if s_count != 1:
        raise ValueError("There must be exactly one 'S'")
    if e_count != 1:
        raise ValueError("There must be exactly one 'E'")

    if start is None or end is None:
        raise ValueError("Start and Exit must be present")

    # BFS to find shortest path
    rows = len(grid)
    cols = len(grid[0])

    visited = set()
    visited.add(start)
    queue = deque([(start[0], start[1], 0)])  # (row, col, steps)

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    while queue:
        r, c, steps = queue.popleft()

        if (r, c) == end:
            return steps

        for dr, dc in directions:
            nr, nc = r + dr, c + dc

            if 0 <= nr < rows and 0 <= nc < cols:
                if (nr, nc) not in visited:
                    cell = grid[nr][nc]
                    if cell in {'S', 'E', '.'}:
                        visited.add((nr, nc))
                        queue.append((nr, nc, steps + 1))

    return -1
