  const normalize = (str) => [...str];

  const normalizedStrs = strs.map(s => normalize(s));

  if (normalizedStrs.some(s => s.length === 0)) {
    return '';
  }

  const minLength = Math.min(...normalizedStrs.map(s => s.length));

  let commonPrefix = [];

  for (let i = 0; i < minLength; i++) {
    const char = normalizedStrs[0][i];
    let match = true;

    for (let j = 1; j < normalizedStrs.length; j++) {
      if (normalizedStrs[j][i] !== char) {
        match = false;
        break;
      }
    }

    if (match) {
      commonPrefix.push(char);
    } else {
      break;
    }
  }

  return commonPrefix.join('');
}

