def merge_intervals(intervals):
    if not intervals:
        return []

    # Validate and create a deep copy to avoid modifying input
    processed = []
    for pair in intervals:
        start, end = pair[0], pair[1]
        if start > end:
            raise ValueError("Invalid interval: start must not be greater than end")
        processed.append([start, end])

    # Sort by start time
    processed.sort(key=lambda x: x[0])

    merged = []
    current_start, current_end = processed[0]

    for start, end in processed[1:]:
        # If intervals overlap or touch (end of one equals start of next)
        if start <= current_end:
            if end > current_end:
                current_end = end
        else:
            # No overlap, add current and move to next
            merged.append([current_start, current_end])
            current_start, current_end = start, end

    # Append the final interval
    merged.append([current_start, current_end])

    return merged

