from typing import List

def maze_steps(grid: List[str]) -> int:
    if not grid:
        raise ValueError("Grid cannot be empty")

    row_len = len(grid[0])
    valid_chars = {'S', 'E', '#', '.'}
    start = None
    end = None

    # Validate grid structure and content
    for r, row in enumerate(grid):
        if len(row) != row_len:
            raise ValueError("All rows must have the same length")
        for c, ch in enumerate(row):
            if ch not in valid_chars:
                raise ValueError(f"Invalid character '{ch}' in grid")
            if ch == 'S':
                if start is not None:
                    raise ValueError("There must be exactly one 'S'")
                start = (r, c)
            elif ch == 'E':
                if end is not None:
                    raise ValueError("There must be exactly one 'E'")
                end = (r, c)

    if start is None or end is None:
        raise ValueError("Grid must contain exactly one 'S' and exactly one 'E'")

    # BFS to find shortest path
    queue = deque([(start[0], start[1], 0)])
    visited = {start}
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    rows = len(grid)
    cols = len(grid[0])

    while queue:
        r, c, dist = queue.popleft()
        if (r, c) == end:
            return dist

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if (nr, nc) not in visited:
                    cell = grid[nr][nc]
                    if cell != '#':  # Can move through '.', 'S', 'E'
                        visited.add((nr, nc))
                        queue.append((nr, nc, dist + 1))

    return -1
