  const seenKeys = [];

  for (let i = 0; i < items.length; i++) {
    const item = items[i];
    const key = keyFn(item, i);

    if (!result.has(key)) {
      result.set(key, [item]);
      seenKeys.push(key);
    } else {
      result.get(key).push(item);
    }
  }

  // Reorder the map to preserve insertion order of keys
  const orderedResult = new Map();
  for (const key of seenKeys) {
    orderedResult.set(key, result.get(key));
  }

  return orderedResult;
}

