from collections import deque
from typing import List

def maze_steps(grid: List[str]) -> int:
    if not grid:
        raise ValueError("Grid must not be empty")

    row_len = len(grid[0])
    allowed_chars = {'S', 'E', '#', '.'}
    start = None
    end = None

    for r, row in enumerate(grid):
        if len(row) != row_len:
            raise ValueError("All rows must have the same length")
        for c, ch in enumerate(row):
            if ch not in allowed_chars:
                raise ValueError("Invalid character in grid")
            if ch == 'S':
                if start is not None:
                    raise ValueError("Exactly one S must exist")
                start = (r, c)
            elif ch == 'E':
                if end is not None:
                    raise ValueError("Exactly one E must exist")
                end = (r, c)

    if start is None or end is None:
        raise ValueError("Exactly one S and one E must exist")

    rows, cols = len(grid), row_len
    queue = deque([(start[0], start[1], 0)])
    visited = set([start])

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    while queue:
        r, c, dist = queue.popleft()
        if (r, c) == end:
            return dist

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if (nr, nc) not in visited and grid[nr][nc] != '#':
                    visited.add((nr, nc))
                    queue.append((nr, nc, dist + 1))

    return -1
