  const month = parseInt(parts[1], 10);
  const day = parseInt(parts[2], 10);

  if (month < 1 || month > 12) {
    throw new RangeError('Invalid month.');
  }

  const daysInMonth = new Date(Date.UTC(year, month, 0)).getUTCDate();
  if (day < 1 || day > daysInMonth) {
    throw new RangeError('Invalid day for the given month.');
  }

  return { year, month, day };
}

function isLeapYear(year) {
  return (year % 4 === 0 && year % 100 !== 0) || (year % 400 === 0);
}

function getActualBirthdayDay(year, month, originalDay) {
  // If born on Feb 29, treat birthday as March 1 in non-leap years
  if (month === 2 && originalDay === 29) {
    if (!isLeapYear(year)) {
      return 1; // March 1st
    }
    return 29;
  }
  return originalDay;
}

function ageOn(birth, on) {
