  const onDate = parseDate(on);

  if (onDate.year < birthDate.year ||
      (onDate.year === birthDate.year && onDate.month < birthDate.month) ||
      (onDate.year === birthDate.year && onDate.month === birthDate.month && onDate.day < birthDate.day)) {
