  const birthdayDay = getActualBirthdayDay(onDate.year, birthdayMonth, birthDate.day);

  const onMonth = onDate.month;
  const onDay = onDate.day;

  // Check if birthday has occurred this year
  if (onMonth < birthdayMonth) {
    age--;
  } else if (onMonth === birthdayMonth && onDay < birthdayDay) {
    age--;
  }

  return age;
}

