                raise ValueError("Invalid character in grid")

    start = None
    end = None

    for r, row in enumerate(grid):
        for c, ch in enumerate(row):
            if ch == 'S':
                if start is not None:
                    raise ValueError("Exactly one S expected")
                start = (r, c)
            elif ch == 'E':
                if end is not None:
                    raise ValueError("Exactly one E expected")
                end = (r, c)

    if start is None or end is None:
        raise ValueError("Exactly one S and exactly one E expected")

    rows = len(grid)
    cols = len(grid[0])
    visited = [[False] * cols for _ in range(rows)]
    queue = deque()

    queue.append((start[0], start[1], 0))
    visited[start[0]][start[1]] = True

    while queue:
        r, c, dist = queue.popleft()
        if (r, c) == end:
            return dist

